  (1, 'About Me', 'The child''s body, feelings, clothes, and personal identity.', '{"vi":{"name":"Bản thân em","description":"Cơ thể, cảm xúc, quần áo và những điều cơ bản về bản thân."}}'),
  (2, 'Family and Friends', 'Family members, friends, and everyday relationships.', '{"vi":{"name":"Gia đình và bạn bè","description":"Các thành viên gia đình, bạn bè và những mối quan hệ gần gũi."}}'),
  (3, 'Home and Daily Life', 'Home, routines, and simple everyday responsibilities.', '{"vi":{"name":"Nhà cửa và sinh hoạt hằng ngày","description":"Ngôi nhà, thói quen và các việc hằng ngày đơn giản."}}'),
  (4, 'School and Learning', 'Classroom objects, school life, and early learning.', '{"vi":{"name":"Trường học và học tập","description":"Đồ dùng lớp học, đời sống ở trường và việc học cơ bản."}}'),
  (5, 'Food and Drink', 'Meals, food groups, snacks, and drinks.', '{"vi":{"name":"Đồ ăn và thức uống","description":"Bữa ăn, nhóm thực phẩm, đồ ăn nhẹ và thức uống."}}'),
  (6, 'Animals', 'Pets, farm animals, and familiar wild animals.', '{"vi":{"name":"Động vật","description":"Thú cưng, động vật trang trại và các động vật hoang dã quen thuộc."}}'),
  (7, 'Nature and Weather', 'Weather, seasons, plants, and the natural world.', '{"vi":{"name":"Thiên nhiên và thời tiết","description":"Thời tiết, mùa, cây cối và thế giới tự nhiên."}}'),
  (8, 'Play and Hobbies', 'Toys, games, sports, and free-time activities.', '{"vi":{"name":"Vui chơi và sở thích","description":"Đồ chơi, trò chơi, thể thao và hoạt động lúc rảnh."}}'),
  (9, 'Travel and Places', 'Transport and familiar places in the community.', '{"vi":{"name":"Di chuyển và địa điểm","description":"Phương tiện đi lại và các địa điểm quen thuộc trong cộng đồng."}}'),
  (10, 'People and Community', 'Jobs, community helpers, and caring for others.', '{"vi":{"name":"Con người và cộng đồng","description":"Nghề nghiệp, những người giúp đỡ cộng đồng và quan tâm người khác."}}'),
  (11, 'Early Concepts', 'Numbers, colours, shapes, size, time, and basic comparisons.', '{"vi":{"name":"Khái niệm nền tảng","description":"Số đếm, màu sắc, hình khối, kích thước, thời gian và so sánh cơ bản."}}'),
  (12, 'Celebrations', 'Birthdays, holidays, and simple family traditions.', '{"vi":{"name":"Lễ kỷ niệm","description":"Sinh nhật, ngày lễ và các truyền thống gia đình đơn giản."}}');
